function renderJobs(){jobsMode='list';roomId='';clearInterval(roomTimer);const d=jobData;$('jobs').innerHTML='<div class="card"><div class="vh-top"><h2 style="margin:0">공사·현장미팅</h2><button class="button" type="button" onclick="jobForm()">+ 새 공사 만들기</button></div><p class="desc">공사를 만들고 참여 업체를 배정한 뒤, 현장 미팅 방을 만들어 QR로 참석을 받습니다.</p></div>'+waitCard()+(d.jobs.map(j=>'<div class="card"><div class="vh-top"><div><h2 style="margin:0">'+escapeText(j.title)+'</h2><div class="muted">'+escapeText(j.kindLabel)+' · '+escapeText(j.storeName)+(j.storeCode?' ('+escapeText(j.storeCode)+')':'')+' · '+escapeText(j.startDate)+(j.endDate?' ~ '+escapeText(j.endDate):'')+' · 주관 '+escapeText(j.hostName)+'</div></div><div class="row"><button class="button ghost" type="button" onclick="jobForm(\''+escapeText(j.id)+'\')">수정</button><button class="button ghost danger" type="button" onclick="delJob(\''+escapeText(j.id)+'\')">삭제</button></div></div><div class="desc" style="margin-top:8px"><b>참여 업체 '+j.vendors.length+'곳</b> · '+(j.vendors.map(v=>escapeText(v.company)+' <span class="muted">('+escapeText(v.trade)+')</span>').join(', ')||'없음')+'</div><div class="line"></div><div class="row" style="justify-content:space-between"><b>작업허가서 <span class="muted">'+(j.permitTotal||0)+'건</span>'+(j.permitWaiting?' <span class="cnt">'+j.permitWaiting+'</span> <span class="req" style="font-size:13px">승인 대기</span>':'')+'</b><button class="button ghost" type="button" onclick="openPermitList(\''+escapeText(j.id)+'\')">작업허가서 보기</button></div><div class="line"></div><div class="row" style="justify-content:space-between"><b>현장 미팅</b><button class="button ghost" type="button" onclick="meetForm(\''+escapeText(j.id)+'\')">+ 미팅 방 만들기</button></div>'+(j.meetings.map(m=>'<div class="item"><div class="row" style="justify-content:space-between"><div><b>'+escapeText(m.title)+'</b> '+(m.done?'<span class="pill ok">✔ 실시 완료</span>':m.open?'<span class="pill ok">방 열림</span>':'<span class="pill todo">닫힘 · 실시 전</span>')+'<div class="muted">'+escapeText(m.date)+' '+escapeText(m.time||'')+' · '+escapeText(m.place)+' · 참석 '+m.count+'명'+(m.pending?' · <b style="color:#ce2a4b">확인 대기 '+m.pending+'</b>':'')+'</div></div><div class="row"><button class="button" type="button" onclick="openRoom(\''+escapeText(m.id)+'\')">방 들어가기</button><button class="button ghost danger" type="button" onclick="delMeet(\''+escapeText(m.id)+'\')">삭제</button></div></div></div>').join('')||'<p class="muted">아직 미팅 방이 없습니다.</p>')+'</div>').join('')||'<div class="card"><p class="desc">등록된 공사가 없습니다. [+ 새 공사 만들기]로 시작하세요.</p></div>')}
